BEGIN TRANSACTION;
CREATE TABLE "freelancers" (
"freelancer_id" TEXT,
  "name" TEXT,
  "gender" TEXT,
  "age" REAL,
  "country" TEXT,
  "language" TEXT,
  "primary_skill" TEXT,
  "years_of_experience" REAL,
  "hourly_rate_usd" TEXT,
  "rating" REAL,
  "is_active" INTEGER,
  "client_satisfaction" TEXT
);
COMMIT;
